/// <summary>
/// extension of form AVATCVTable
/// </summary>
[ExtensionOf(formStr(AVATCVTable))]
final class AVATCVTableFrm_Extension
{
    public ObjectIdent  locDocuView;

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void run()
{
    next run();

    this.design().controlName(formControlStr(AVATCVTable, QuickFilterControl)).setFocus();
}

public void avaCreateDocuRef()
{
    DocuRef             newDocuRef;
    KCS_TCVTable        selectedTCVTable;
    RecordInsertList    newDocuRefList = new RecordInsertList(tableNum(DocuRef));

    this.getActualIds();

    for (selectedTCVTable = TCVTable_ds.getFirst(true) ? TCVTable_ds.getFirst(true) : TCVTable_ds.cursor();
    selectedTCVTable;
    selectedTCVTable = TCVTable_ds.getNext())
    {
        if(KCS_TCVTable::find(selectedTCVTable.Id).UseHTMLEditor == NoYes::Yes && DocuType::find(KCS_TCVParameters::find().DocuTypeId).AVA_TCVUseHTMLEditor == NoYes::No)
        {
            throw error("@TCV239");
        }

        if(!actualCompanyId)
        {
            actualCompanyId = curExt();
        }

        newDocuRef.clear();
        newDocuRef.initValue();
        newDocuRef.RefCompanyId     = actualCompanyId;
        newDocuRef.RefTableId       = actualTableId;
        newDocuRef.RefRecId         = actualRecId;
        newDocuRef.TypeId           = KCS_TCVParameters::docuType();
        newDocuRef.KCS_TCVInitFromDocuType();
        newDocuRef.KCS_TCVinitCopyTo();
        newDocuRef.Name             = selectedTCVTable.Name;
        newDocuRef.KCS_TCVGroupId   = selectedTCVTable.GroupId;
        newDocuRef.AVAFormat        = selectedTCVTable.AVAFormat;
        newDocuRef.AVASortDesc      = selectedTCVTable.AVASortDesc;

        if (DocuType::find(newDocuRef.TypeId).AVA_TCVUseHTMLEditor == NoYes::Yes)
        {
            newDocuRef.Notes = selectedTCVTable.TCVTableLanguage(LanguageFilter.getText(LanguageFilter.selection())).Conserve;
        }
        else
        {
            newDocuRef.Notes = System.Text.RegularExpressions.Regex::Replace(selectedTCVTable.TCVTableLanguage(LanguageFilter.getText(LanguageFilter.selection())).Conserve, "<.*?>", "");
        }

        newDocuRefList.add(newDocuRef);
    }
    newDocuRefList.insertDatabase();

    this.closeOk();

}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    next  init();
    AVATCVDocu_Derived docuInstance = Docu::Instance();
    if (docuInstance)
    {
        ObjectIdent docuView = docuInstance.docuView();
        if (docuView && docuView.object())
        {
            locDocuView = docuView;
            docuInstance.clearDocuView(); //ensure that form is removed from infolog object
        }
    }
}

/// <summary>
/// designed from AVA
/// </summary>
public void close()
{
    next close();
    AVATCVDocu_Derived docuInstance = Docu::Instance();
    if (docuInstance)
    {
        ObjectIdent docuView = docuInstance.docuView();
        if(docuView == null && this.args().caller() && this.args().caller().handle() == className2Id('formRun'))
        {
            docuInstance.resetDocuView(this.args().caller());

            if (infolog.parmLastActivatedForm() && infolog.parmLastActivatedForm().object())
            {
                docuInstance.reSearch(infolog.parmLastActivatedForm().object());
            }
        }
    }

    if(this.args().caller() && this.args().caller().handle() == className2Id('formRun'))
    {
        if (this.args().dataset() == tableNum(DocuRef))
        {
            FormRun             formRun = this.args().caller();
            FormDataSource      docuRef_DS = formRun.dataSource('DocuRef');
            if (docuRef_DS)
            {
                docuRef_DS.executeQuery();
            }
        }
    }

}
